raw_levels = [1, 0, 0, 1]
for raw in raw_levels:
    pressed = raw == 0
    if pressed:
        led = 1
    else:
        led = 0
    print(raw, led)

def distance_cm(raw):
    if raw < 200 or raw > 800:
        return None
    return 10 + (raw - 200) / (800 - 200) * (40 - 10)

for raw in [200, 500, 800, 900]:
    value = distance_cm(raw)
    if value is None:
        print(raw, "unknown")
    else:
        print(raw, round(value, 1), "cm")

for state in ["idle", "forward", "stop"]:
    if state == "forward":
        command = "FORWARD"
        request_percent = 50
    else:
        command = "STOP"
        request_percent = 0
    print(state, command, request_percent)

def distance_decision(distance_cm):
    if distance_cm is None or distance_cm <= 20:
        return "stop"
    return "forward"

for distance_cm in [50, 20, 15, None]:
    print(distance_cm, distance_decision(distance_cm))
